[CmdletBinding()]param([string]$LudiiJar='C:\Users\verti\Ludii-1.3.14.jar',[switch]$Smoke)
$ErrorActionPreference='Stop';$scriptDir=Split-Path -Parent $MyInvocation.MyCommand.Path;$issue=[IO.Path]::GetFullPath((Join-Path $scriptDir '..'));$repo=[IO.Path]::GetFullPath((Join-Path $issue '..\..'));$config=Get-Content -Raw (Join-Path $issue 'config.json')|ConvertFrom-Json;$results=Join-Path $issue $(if($Smoke){'results-smoke'}else{'results'});$raw=Join-Path $results 'raw';New-Item -ItemType Directory -Force -Path $raw|Out-Null
& (Join-Path $scriptDir 'New-TrialSources.ps1') -Smoke:$Smoke;if($LASTEXITCODE){throw 'Manifest failed'}
$sources=if($Smoke){@($config.analysis_sources|Where-Object source_issue -eq 62|ForEach-Object{[pscustomobject]@{source_issue=62;board=$_.board;id=$_.id;iteration_limit=$_.iteration_limit;trial_root=("experiments/issue-62/results-smoke/trials/{0}"-f$_.id)}})}else{@($config.analysis_sources)}
$games=Join-Path $raw 'games.csv';$placements=Join-Path $raw 'placements.csv';$states=Join-Path $raw 'turn-states.csv';$replay=Join-Path $scriptDir 'HeitanScaleReplay.java';$game=Join-Path $repo $config.game;$started=[DateTime]::UtcNow
Push-Location $issue;try{for($i=0;$i-lt$sources.Count;$i++){$source=$sources[$i];& java -cp $LudiiJar $replay $game $source.board $source.id $source.iteration_limit (Join-Path $repo $source.trial_root) $games $placements $states ($i-gt0).ToString().ToLowerInvariant();if($LASTEXITCODE){throw "Replay failed: issue $($source.source_issue)/$($source.id)"}}}finally{Pop-Location}
$gameRows=@(Import-Csv $games);$manifest=@(Import-Csv (Join-Path $results 'trial-sources.csv'));$gameKeys=@($gameRows|ForEach-Object{"$($_.board)|$($_.experiment_id)|$([int]$_.game_index)"}|Sort-Object);$manifestKeys=@($manifest|ForEach-Object{"$($_.board)|$($_.experiment_id)|$([int]$_.game_index)"}|Sort-Object);if((Compare-Object $gameKeys $manifestKeys).Count){throw 'Replay keys differ from manifest'}
& node --test (Join-Path $scriptDir 'analyze-scale.test.mjs');if($LASTEXITCODE){throw 'Analysis tests failed'}
if($Smoke){$tempConfig=Join-Path $issue 'config.json';$analysisResults=$results;& node (Join-Path $scriptDir 'analyze-scale.mjs') $analysisResults}else{& node (Join-Path $scriptDir 'analyze-scale.mjs')};if($LASTEXITCODE){throw 'Analysis failed'}
$environment=[ordered]@{schema_version=1;smoke=$Smoke.IsPresent;generated_at_utc=[DateTime]::UtcNow.ToString('o');elapsed_seconds=[Math]::Round(([DateTime]::UtcNow-$started).TotalSeconds,3);games=$gameRows.Count;ludii_version=$config.ludii_version;ludii_jar_sha256=(Get-FileHash $LudiiJar -Algorithm SHA256).Hash.ToLowerInvariant();config_sha256=(Get-FileHash (Join-Path $issue 'config.json') -Algorithm SHA256).Hash.ToLowerInvariant();game_sha256=(Get-FileHash $game -Algorithm SHA256).Hash.ToLowerInvariant();replay_sha256=(Get-FileHash $replay -Algorithm SHA256).Hash.ToLowerInvariant();analysis_sha256=(Get-FileHash (Join-Path $scriptDir 'analyze-scale.mjs') -Algorithm SHA256).Hash.ToLowerInvariant();trial_sources_sha256=(Get-FileHash (Join-Path $results 'trial-sources.csv') -Algorithm SHA256).Hash.ToLowerInvariant();git_commit=(& git -c "safe.directory=$($repo.Replace('\','/'))" -C $repo rev-parse HEAD).Trim();java=(& java --version|Select-Object -First 1);node=(& node --version)};$environment|ConvertTo-Json -Depth 4|Set-Content (Join-Path $results 'environment.json') -Encoding UTF8;Write-Host "Replayed and analyzed $($gameRows.Count) games"
